# AI-generated by OpenAI Codex, 2026-11-14.
"""Interaction checks using the real Streamlit app and repository data."""

import datetime as dt
import json
from pathlib import Path
import sys
import unittest

from streamlit.testing.v1 import AppTest

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))


class InterfaceTests(unittest.TestCase):
    def open_sites(self):
        app = AppTest.from_file(str(ROOT / "src/app.py"), default_timeout=20).run()
        self.assertFalse(app.exception)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        return app

    def test_mission_values_survive_back_navigation(self):
        app = AppTest.from_file(str(ROOT / "src/app.py"), default_timeout=20).run()
        app.date_input[0].set_value(dt.date(2029, 6, 8))
        app.time_input[0].set_value(dt.time(17, 30))
        app.slider[0].set_value(27)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        app.button[0].click().run()
        self.assertEqual(app.date_input[0].value, dt.date(2029, 6, 8))
        self.assertEqual(app.time_input[0].value, dt.time(17, 30))
        self.assertEqual(app.slider[0].value, 27)

    def test_incomplete_mission_stays_on_form(self):
        app = AppTest.from_file(str(ROOT / "src/app.py"), default_timeout=20).run()
        app.date_input[0].set_value(None)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.date_input), 1)
        self.assertTrue(app.error)

    def test_views_and_date_scan_use_current_mission(self):
        app = self.open_sites()
        app.radio[0].set_value("Elevation over time").run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.get("plotly_chart")), 2)
        app.radio[0].set_value("Visibility margin over time").run()
        self.assertFalse(app.exception)
        app.checkbox[0].check().run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.get("plotly_chart")), 3)
        spec = json.loads(app.get("plotly_chart")[2].proto.spec)
        self.assertEqual(len(spec["data"][0]["y"]), 13)
        self.assertEqual(len(spec["data"][0]["x"]), 366)

    def test_last_landing_date_supports_maximum_mission(self):
        app = AppTest.from_file(str(ROOT / "src/app.py"), default_timeout=20).run()
        app.date_input[0].set_value(dt.date(2030, 12, 31))
        app.time_input[0].set_value(dt.time(23, 59))
        app.slider[0].set_value(60)
        app.button[0].click().run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.selectbox[0].options), 13)

    def test_all_failed_sites_remain_visible_with_explanations(self):
        app = self.open_sites()
        for slider in app.slider:
            if slider.label == "Long-term sunlight":
                slider.set_value(100)
            if slider.label == "Long-term Earth visibility":
                slider.set_value(100)
        app.run()
        self.assertFalse(app.exception)
        self.assertEqual(len(app.selectbox[0].options), 13)
        text = " ".join(str(e.value) for e in app.warning)
        self.assertIn("No candidate", text)
        self.assertIn("long-term sunlight below limit", text)
        self.assertIn("long-term Earth visibility below limit", text)

    def test_calibrated_estimates_and_unavailable_slope_are_distinct(self):
        app = self.open_sites()
        text = " ".join(str(e.value) for e in app.markdown)
        for label in ["Slope", "Custom coordinates"]:
            self.assertIn(label, text)
        self.assertGreaterEqual(text.lower().count("not available yet"), 2)
        self.assertIn("estimate anchored to nasa long-term data", text.lower())
        self.assertTrue(any(m.label == "Window sunlight" for m in app.metric))
        self.assertTrue(any(m.label == "Window Earth contact" for m in app.metric))

    def test_selection_updates_details_and_map_in_same_run(self):
        app = self.open_sites()
        app.selectbox[0].select("Faustini Rim A").run()
        self.assertFalse(app.exception)
        self.assertTrue(any("Faustini Rim A" in e.value for e in app.subheader))
        spec = json.loads(app.get("plotly_chart")[0].proto.spec)
        trace = next(t for t in spec["data"] if "customdata" in t)
        index = [r[0] for r in trace["customdata"]].index("Faustini Rim A")
        self.assertEqual(trace["marker"]["line"]["width"][index], 3)

    def test_map_uses_supplied_coordinates_without_displacing_overlap(self):
        from sites import load_sites

        app = self.open_sites()
        spec = json.loads(app.get("plotly_chart")[0].proto.spec)
        trace = next(t for t in spec["data"] if "customdata" in t)
        positions = {item[0]: (x, y) for item, x, y in zip(trace["customdata"], trace["x"], trace["y"])}
        for row in load_sites().itertuples():
            self.assertEqual(positions[row.site], (row.x_km, row.y_km))
        self.assertNotEqual(positions["de Gerlache Rim"], positions["de Gerlache Rim 2"])
        self.assertEqual(spec["layout"]["yaxis"]["scaleanchor"], "x")
        self.assertEqual(spec["layout"]["yaxis"]["scaleratio"], 1)


if __name__ == "__main__":
    unittest.main()
